import { useState, type FormEvent } from 'react';
import {
  Plus,
  Edit2,
  Trash2,
  RefreshCw,
  ChevronUp,
  ChevronDown,
  ShieldCheck,
  FileText,
  Eye,
  Settings,
  Share2,
  Lock,
  Cookie,
  Mail,
  HelpCircle,
  Tag,
  Sparkles,
  Globe,
  Star,
  CheckCircle2,
  AlertTriangle,
  Award,
  Zap,
  Lightbulb,
  Package,
  Save,
  Upload,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import { useI18n } from '@/i18n/I18nContext';
import { usePrivacyPolicy, type PrivacySection } from '@/hooks/usePrivacyPolicy';
import { createI18nText, type I18nText } from '@/lib/i18n-text';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useSyncService } from '@/context/SyncServiceContext';
import SyncStatusBadge from '@/components/SyncStatusBadge';

const ICON_OPTIONS = [
  { name: 'FileText', icon: FileText },
  { name: 'Eye', icon: Eye },
  { name: 'Settings', icon: Settings },
  { name: 'Share2', icon: Share2 },
  { name: 'Lock', icon: Lock },
  { name: 'ShieldCheck', icon: ShieldCheck },
  { name: 'Cookie', icon: Cookie },
  { name: 'Mail', icon: Mail },
  { name: 'HelpCircle', icon: HelpCircle },
  { name: 'Tag', icon: Tag },
  { name: 'Sparkles', icon: Sparkles },
  { name: 'Globe', icon: Globe },
  { name: 'Star', icon: Star },
  { name: 'CheckCircle2', icon: CheckCircle2 },
  { name: 'AlertTriangle', icon: AlertTriangle },
  { name: 'Award', icon: Award },
  { name: 'Zap', icon: Zap },
  { name: 'Lightbulb', icon: Lightbulb },
  { name: 'Package', icon: Package },
];

interface SectionForm {
  icon: string;
  titleEn: string;
  titleZh: string;
  titleEs: string;
  titleJa: string;
  contentEn: string;
  contentZh: string;
  contentEs: string;
  contentJa: string;
}

const emptyForm = (): SectionForm => ({
  icon: 'FileText',
  titleEn: '',
  titleZh: '',
  titleEs: '',
  titleJa: '',
  contentEn: '',
  contentZh: '',
  contentEs: '',
  contentJa: '',
});

function sectionToForm(section: PrivacySection): SectionForm {
  return {
    icon: section.icon,
    titleEn: section.title.en,
    titleZh: section.title.zh,
    titleEs: section.title.es,
    titleJa: section.title.ja,
    contentEn: section.content.en,
    contentZh: section.content.zh,
    contentEs: section.content.es,
    contentJa: section.content.ja,
  };
}

function formToTitle(form: SectionForm): I18nText {
  return createI18nText(form.titleEn, form.titleZh, form.titleEs, form.titleJa);
}

function formToContent(form: SectionForm): I18nText {
  return createI18nText(form.contentEn, form.contentZh, form.contentEs, form.contentJa);
}

export default function AdminPrivacyPolicyPage() {
  const { adminT } = useI18n();
  const { data, loading, updateSection, addSection, deleteSection, moveSection, resetToDefaults } =
    usePrivacyPolicy();
  const { markDirty, syncModule, syncJsonFile, getStatus } = useSyncService();
  const syncStatus = getStatus('privacy');

  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<SectionForm>(emptyForm());
  const [resetting, setResetting] = useState(false);
  const [saving, setSaving] = useState(false);
  const [activeTab, setActiveTab] = useState<'title' | 'content'>('title');

  const resetForm = () => {
    setForm(emptyForm());
    setEditingId(null);
    setActiveTab('title');
  };

  const openCreate = () => {
    resetForm();
    setDialogOpen(true);
  };

  const openEdit = (section: PrivacySection) => {
    setForm(sectionToForm(section));
    setEditingId(section.id);
    setActiveTab('title');
    setDialogOpen(true);
  };

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    if (!form.titleEn.trim() || !form.contentEn.trim()) {
      toast.error('English title and content are required');
      return;
    }
    setSaving(true);
    await new Promise((r) => setTimeout(r, 300));
    if (editingId) {
      const ok = updateSection(editingId, {
        icon: form.icon,
        title: formToTitle(form),
        content: formToContent(form),
      });
      if (ok) {
        toast.success('Privacy section updated');
        markDirty('privacy');
        setDialogOpen(false);
      } else {
        toast.error('Failed to update section');
      }
    } else {
      const ok = addSection({
        icon: form.icon,
        title: formToTitle(form),
        content: formToContent(form),
      });
      if (ok) {
        toast.success('Privacy section added');
        markDirty('privacy');
        setDialogOpen(false);
      } else {
        toast.error('Failed to add section');
      }
    }
    setSaving(false);
  };

  const handleDelete = async (sectionId: string) => {
    if (!window.confirm('Are you sure you want to delete this section?')) return;
    const ok = deleteSection(sectionId);
    if (ok) {
      toast.success('Section deleted');
      markDirty('privacy');
    }
    else toast.error('Failed to delete section');
  };

  const handleMove = (sectionId: string, direction: 'up' | 'down') => {
    moveSection(sectionId, direction);
  };

  const handleReset = async () => {
    if (!window.confirm('Are you sure you want to reset privacy policy to defaults?')) return;
    setResetting(true);
    await new Promise((r) => setTimeout(r, 400));
    const ok = resetToDefaults();
    setResetting(false);
    if (ok) {
      toast.success('Privacy policy reset to defaults');
      markDirty('privacy');
    }
    else toast.error('Failed to reset');
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <RefreshCw className="size-6 animate-spin text-muted-foreground" />
      </div>
    );
  }

  const sortedSections = [...data.sections].sort((a, b) => a.order - b.order);

  return (
    <div className="space-y-6">
      <PageBreadcrumb
        firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
        items={[{ label: adminT('admin.privacyPolicy') }]}
      />

      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold tracking-tight">{adminT('admin.privacyPolicy')}</h1>
          <p className="text-sm text-muted-foreground mt-1">
            {adminT('admin.privacyPolicyDesc')} {data.lastUpdated}
          </p>
        </div>
        <div className="flex items-center gap-2 flex-wrap">
          <SyncStatusBadge status={syncStatus} />
          <Button
            variant="outline"
            size="sm"
            onClick={() =>
              syncModule('privacy', 'Privacy Policy', async (config) => {
                await syncJsonFile(
                  config,
                  'data/privacy.json',
                  data,
                  'Update privacy policy'
                );
              })
            }
            disabled={syncStatus === 'syncing'}
            className="text-xs h-9"
          >
            <Upload className="size-3.5 mr-1.5" />
            Sync to GitHub
          </Button>
          <Button variant="outline" size="sm" onClick={handleReset} disabled={resetting}>
            {resetting && <RefreshCw className="size-4 mr-2 animate-spin" />}
            Reset to Defaults
          </Button>
          <Button size="sm" onClick={openCreate}>
            <Plus className="size-4 mr-1.5" />
            Add Section
          </Button>
        </div>
      </div>

      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <ShieldCheck className="size-5 text-primary" />
            Privacy Policy Sections
          </CardTitle>
          <CardDescription>
            Reorder, edit, or add sections to the privacy policy page
          </CardDescription>
        </CardHeader>
        <CardContent className="p-0">
          <div className="w-full overflow-x-auto">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="whitespace-nowrap w-[60px]">Order</TableHead>
                  <TableHead className="whitespace-nowrap w-[60px]">Icon</TableHead>
                  <TableHead>Title (EN)</TableHead>
                  <TableHead className="whitespace-nowrap w-[120px] text-right">Actions</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {sortedSections.map((section) => {
                  const IconComponent =
                    ICON_OPTIONS.find((o) => o.name === section.icon)?.icon ?? FileText;
                  return (
                    <TableRow key={section.id}>
                      <TableCell className="font-mono text-xs text-muted-foreground">
                        {section.order}
                      </TableCell>
                      <TableCell>
                        <div className="w-8 h-8 rounded bg-primary/10 flex items-center justify-center">
                          <IconComponent className="size-4 text-primary" />
                        </div>
                      </TableCell>
                      <TableCell className="font-medium">{section.title.en}</TableCell>
                      <TableCell>
                        <div className="flex items-center justify-end gap-1">
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => handleMove(section.id, 'up')}
                            disabled={section.order === 1}
                            aria-label="Move up"
                          >
                            <ChevronUp className="size-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => handleMove(section.id, 'down')}
                            disabled={section.order === sortedSections.length}
                            aria-label="Move down"
                          >
                            <ChevronDown className="size-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => openEdit(section)}
                            aria-label="Edit"
                          >
                            <Edit2 className="size-4" />
                          </Button>
                          <Button
                            variant="ghost"
                            size="icon"
                            onClick={() => handleDelete(section.id)}
                            aria-label="Delete"
                            className="text-destructive hover:text-destructive"
                          >
                            <Trash2 className="size-4" />
                          </Button>
                        </div>
                      </TableCell>
                    </TableRow>
                  );
                })}
                {sortedSections.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={4} className="text-center py-8 text-muted-foreground">
                      No sections yet. Click &quot;Add Section&quot; to create one.
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>

      {/* Edit/Create Dialog */}
      <Dialog open={dialogOpen} onOpenChange={(open) => !open && setDialogOpen(false)}>
        <DialogContent className="sm:max-w-[720px] max-h-[85vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle>{editingId ? 'Edit Section' : 'Add Section'}</DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-5">
            <div className="space-y-2">
              <Label htmlFor="icon">Icon</Label>
              <Select value={form.icon} onValueChange={(v) => setForm({ ...form, icon: v })}>
                <SelectTrigger id="icon">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {ICON_OPTIONS.map((opt) => {
                    const I = opt.icon;
                    return (
                      <SelectItem key={opt.name} value={opt.name} className="flex items-center gap-2">
                        <div className="flex items-center gap-2">
                          <I className="size-4" />
                          <span>{opt.name}</span>
                        </div>
                      </SelectItem>
                    );
                  })}
                </SelectContent>
              </Select>
            </div>

            {/* Tabs */}
            <div className="flex items-center gap-1 border-b border-border">
              <button
                type="button"
                onClick={() => setActiveTab('title')}
                className={`px-4 py-2 text-sm font-medium border-b-2 -mb-px transition-colors ${
                  activeTab === 'title'
                    ? 'border-primary text-primary'
                    : 'border-transparent text-muted-foreground hover:text-foreground'
                }`}
              >
                Titles
              </button>
              <button
                type="button"
                onClick={() => setActiveTab('content')}
                className={`px-4 py-2 text-sm font-medium border-b-2 -mb-px transition-colors ${
                  activeTab === 'content'
                    ? 'border-primary text-primary'
                    : 'border-transparent text-muted-foreground hover:text-foreground'
                }`}
              >
                Content
              </button>
            </div>

            {activeTab === 'title' && (
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="titleEn">Title - English *</Label>
                  <Input
                    id="titleEn"
                    value={form.titleEn}
                    onChange={(e) => setForm({ ...form, titleEn: e.target.value })}
                    placeholder="Section title in English"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="titleZh">标题 - 中文</Label>
                  <Input
                    id="titleZh"
                    value={form.titleZh}
                    onChange={(e) => setForm({ ...form, titleZh: e.target.value })}
                    placeholder="章节标题（中文）"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="titleEs">Título - Español</Label>
                  <Input
                    id="titleEs"
                    value={form.titleEs}
                    onChange={(e) => setForm({ ...form, titleEs: e.target.value })}
                    placeholder="Título de la sección en español"
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="titleJa">タイトル - 日本語</Label>
                  <Input
                    id="titleJa"
                    value={form.titleJa}
                    onChange={(e) => setForm({ ...form, titleJa: e.target.value })}
                    placeholder="セクションタイトル（日本語）"
                  />
                </div>
              </div>
            )}

            {activeTab === 'content' && (
              <div className="space-y-4">
                <div className="space-y-2">
                  <Label htmlFor="contentEn">Content - English *</Label>
                  <Textarea
                    id="contentEn"
                    value={form.contentEn}
                    onChange={(e) => setForm({ ...form, contentEn: e.target.value })}
                    placeholder="Section content in English. Use blank lines for paragraph breaks."
                    rows={8}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="contentZh">内容 - 中文</Label>
                  <Textarea
                    id="contentZh"
                    value={form.contentZh}
                    onChange={(e) => setForm({ ...form, contentZh: e.target.value })}
                    placeholder="章节内容（中文）。空行分段。"
                    rows={6}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="contentEs">Contenido - Español</Label>
                  <Textarea
                    id="contentEs"
                    value={form.contentEs}
                    onChange={(e) => setForm({ ...form, contentEs: e.target.value })}
                    placeholder="Contenido de la sección en español."
                    rows={6}
                  />
                </div>
                <div className="space-y-2">
                  <Label htmlFor="contentJa">内容 - 日本語</Label>
                  <Textarea
                    id="contentJa"
                    value={form.contentJa}
                    onChange={(e) => setForm({ ...form, contentJa: e.target.value })}
                    placeholder="セクションの内容（日本語）。"
                    rows={6}
                  />
                </div>
              </div>
            )}

            <DialogFooter>
              <Button
                type="button"
                variant="outline"
                onClick={() => setDialogOpen(false)}
              >
                Cancel
              </Button>
              <Button type="submit" disabled={saving}>
                {saving && <Save className="size-4 mr-2 animate-spin" />}
                {editingId ? 'Save Changes' : 'Add Section'}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}
